{
  "application": "ppt-generation",
  "case_id": "case-jetbrains-devecosystem",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 6,
    "audience": "Engineering leaders, CTOs, and developer experience teams evaluating technology strategy and hiring priorities",
    "tone": "data-driven, insightful, professional"
  },
  "brief": {
    "title": "State of Developer Ecosystem 2024: Language Trends, Satisfaction, and Strategic Shifts",
    "one_liner": "Key insights from JetBrains' survey of 23,262 developers on programming language usage, satisfaction, adoption intent, and domain specialization trends from 2017 to 2024.",
    "goal": "Help engineering leaders understand which languages are growing or declining, where developer satisfaction is highest, and how language choice maps to application domains — enabling better technology strategy and hiring decisions."
  },
  "slides": [
    {
      "id": "title",
      "title": "State of Developer Ecosystem 2024: Language Trends, Satisfaction, and Strategic Shifts",
      "objective": "Cover slide introducing the report: JetBrains' annual survey of 23,262 developers worldwide. Set context that this is the most comprehensive snapshot of the developer community, covering languages, tools, AI attitudes, and career trends."
    },
    {
      "id": "language-trends",
      "title": "Python Closes the Gap: 8 Years of Language Usage Shifts",
      "objective": "Present the multi-year language usage trend data (2017-2024) in a line chart or table. Highlight JavaScript peaking at 70% in 2020 before declining to 61% (from 65% in 2017), Python rising from 32% to 57%, TypeScript tripling from 12% to 37%, and PHP dropping from 30% to 17%. Show that the top-5 landscape is reshuffling."
    },
    {
      "id": "primary-language",
      "title": "Python Is Now the #1 Primary Language at 35%",
      "objective": "Show the primary language breakdown with a horizontal bar chart: Python 35%, Java 30%, JavaScript 28%, TypeScript 19%, SQL 17%. Contrast primary usage with adoption intent (all below 6%) to illustrate ecosystem lock-in and the comfort zone effect."
    },
    {
      "id": "developer-satisfaction",
      "title": "TypeScript and Rust Top Developer Satisfaction, Nearly Tied at 199 vs 198",
      "objective": "Display the language satisfaction ranking as a bar chart: TypeScript 199, Rust 198, Python 151, Go 129, Lua 118, C++ 113, Kotlin 113, Shell 100, Dart 93, C 86. Highlight that type-safe, modern-tooling languages dominate the top spots."
    },
    {
      "id": "domain-specialization",
      "title": "Each Language Owns a Domain: AI Belongs to Python, UI to TypeScript",
      "objective": "Present the language-by-domain heatmap or a summary table showing which language dominates each application area. Python leads AI/ML (31%) and data science (28%); TypeScript/JavaScript own UI (62%/58%); Java leads APIs & services (49%); C++ leads system tools & components (27%). Show that language choice is driven by domain, not general preference."
    },
    {
      "id": "strategic-takeaways",
      "title": "What This Means for Your Technology Strategy in 2025",
      "objective": "Summarize actionable insights: (1) Invest in Python for AI/ML teams — it is the undisputed leader; (2) TypeScript is the future of frontend and full-stack; (3) Rust and Go are the growth plays for infrastructure and systems; (4) PHP and Ruby hiring pools are shrinking; (5) Developer satisfaction correlates with type safety and modern tooling — factor this into retention strategy."
    }
  ]
}

